package com.muxigame.city;
import java.util.*;
import net.minecraft.gametest.framework.*;
import net.neoforged.neoforge.gametest.*;

@GameTestHolder(CityMod.ID) @PrefixGameTestTemplate(false)
public class CityTestsFoodFallback {
 @GameTest(template="empty") public static void missingPreparedFoodFallsBackToCookingEvenNearStarvation(GameTestHelper h){try(var f=new CityTestsScale.Fixture(h)){
  CityTestsModel.configure(f);var family=f.r.state.families.values().stream().filter(v->v.city.equals(f.city.id)).findFirst().orElseThrow();var person=f.r.state.people.get(family.members.getFirst());var stores=f.r.stocks(family.id);for(var stock:stores){stock.wheat=stock.bread=0;RuralMeat.clear(stock);}RuralRules.put(stores,false,29);for(var b:f.t.state.businesses.values())if(b.city.equals(f.city.id))b.listed[1]=new TradeRules.Lot();person.nourishment=1;var home=new FamilyLivelihood.Home();home.processor=person.id;home.secondary=true;home.preferPrepared=true;home.credit=2;f.t.state.households.put(family.id,home);long cash=f.t.money(f.s),grain=f.t.grain(f.s);
  h.assertTrue(FamilyLivelihood.processor(f.s,family)&&FamilyLivelihood.cookingNeeded(f.s,person)&&FamilyLivelihood.workFactor(f.s,person)==.5,"Actual missing bread retains a living adult's household cooking, including the last hunger stage");var bakery=f.t.state.businesses.values().stream().filter(b->b.city.equals(f.city.id)&&b.kind.equals("baker")).findFirst().orElseThrow();bakery.listed[1].add(20,2000);h.assertTrue(FamilyLivelihood.cookingNeeded(f.s,person),"A nearly full raw-food store cannot fit the next prepared meal, so visible bread is not an accessible replacement");long grainWithListed=f.t.grain(f.s);FamilyLivelihood.cook(f.s,family);h.assertTrue(RuralRules.count(stores,true)==2&&RuralRules.count(stores,false)==27&&f.t.money(f.s)==cash&&f.t.grain(f.s)==grainWithListed&&grainWithListed==grain+20,"Elapsed cooking credit consumes actual raw material; no food or money grant");
 }h.succeed();}
 @GameTest(template="empty") public static void fictitiousWageDoesNotMakeAnUnpaidHouseholdRejectCooking(GameTestHelper h){try(var f=new CityTestsScale.Fixture(h)){
  CityTestsModel.configure(f);var family=f.r.state.families.values().stream().filter(v->v.city.equals(f.city.id)).findFirst().orElseThrow();var home=new FamilyLivelihood.Home();home.processor=family.members.getFirst();f.t.state.households.put(family.id,home);h.assertTrue(!CityOpportunities.buyPrepared(f.s,family,true),"Unpaid nominal occupation has zero observed opportunity income");
 }h.succeed();}
 @GameTest(template="empty") public static void farmersCanSellActualOverflowWithoutSellingPrivateReserves(GameTestHelper h){try(var f=new CityTestsScale.Fixture(h)){
  CityTestsModel.configure(f);var farmer=f.r.state.people.values().stream().filter(p->p.role==RuralRules.Role.FARMER&&f.village.residents.contains(p.id)).findFirst().orElseThrow();var own=f.r.stocks(farmer.family);for(var stock:own){stock.wheat=stock.bread=0;RuralMeat.clear(stock);}RuralRules.put(own,false,30);farmer.pendingWheat=12;farmer.pendingAge.add(12,.5);var buyer=f.r.state.families.values().stream().filter(v->v.city.equals(f.village.id)&&!v.id.equals(farmer.family)).findFirst().orElseThrow();for(var stock:f.r.stocks(buyer.id)){stock.wheat=stock.bread=0;RuralMeat.clear(stock);}var money=new HashMap<UUID,Long>();for(var p:f.r.state.people.values())money.put(p.id,100L);long cash=money.values().stream().mapToLong(Long::longValue).sum(),grain=f.t.grain(f.s);int got=RuralStalls.household(f.r,buyer,money,8);
  h.assertTrue(got==8&&farmer.pendingWheat==4&&RuralRules.count(own,false)==30,"Direct sale releases only real field overflow after private storage");h.assertTrue(f.t.grain(f.s)==grain&&money.values().stream().mapToLong(Long::longValue).sum()==cash&&f.r.stocks(buyer.id).getFirst().ages[0].groups.getFirst().age==FoodAge.SCALE/2,"Actual grain, cash and freshness are conserved");
 }h.succeed();}
 @GameTest(template="empty") public static void pendingHarvestAndPublicMeatDecayAreIncludedInConservation(GameTestHelper h){try(var f=new CityTestsScale.Fixture(h)){
  CityTestsModel.configure(f);var p=f.r.state.people.values().stream().filter(v->f.city.residents.contains(v.id)).findFirst().orElseThrow();p.pendingWheat=8;p.pendingAge.add(8,.9);f.city.works.resources.put("minecraft:beef",4);f.city.works.foodAges.computeIfAbsent("minecraft:beef",k->new FoodAge.State()).add(4,.9);long grain=f.t.grain(f.s),meat=f.t.meat(f.s);FoodDecay.step(f.s,0);FoodDecay.step(f.s,24000);h.assertTrue(f.t.grain(f.s)+FoodDecay.grain(f.s)==grain&&f.t.meat(f.s)+FoodDecay.meat(f.s)==meat&&p.pendingWheat<8,"Field and public stock lose only explicitly audited spoilage");
 }h.succeed();}
}
